using System.Text.Json;
using System.Security.Cryptography;
using System.Text;
using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Commands;
using MegaCrit.Sts2.Core.Entities.Cards;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.GameActions.Multiplayer;
using MegaCrit.Sts2.Core.Hooks;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Cards;
using MegaCrit.Sts2.Core.Runs;

namespace CombatSolver;
internal sealed partial class UnattendedTestRunner
{
    private async Task RunTaskReturnCapacityAsync(CombatState live, Player player, bool hatchetFirst)
    {
        var enemy = live.Enemies.First(candidate => candidate.IsAlive);
        foreach (RelicModel relic in player.Relics.ToArray()) await RelicCmd.Remove(relic);
        foreach (PowerModel power in live.Creatures.SelectMany(creature => creature.Powers).ToArray())
            await PowerCmd.Remove(power);
        await ClearPlayerPilesAsync(player);
        await SetBlockAsync(player.Creature, 0);await SetBlockAsync(enemy, 0);
        await CreatureCmd.SetMaxHp(enemy, Math.Max(256, enemy.MaxHp));
        await CreatureCmd.SetCurrentHp(enemy, 256);SetEnergy(player, 6);
        foreach (string id in new[] { "BOLAS", "THRUMMING_HATCHET" })
            await InjectCardAsync(live, player, new() { CardId = id, Pile = "Hand" });
        await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
        CombatRootSnapshot playRoot = CombatRootSnapshot.Capture(live);
        ReturnToHandComparisonLane[] playLanes =
        [new("continuous", playRoot.ForkSimulator(), false), new("forked", playRoot.ForkSimulator(), true)];
        await PlayReturningCardAsync(live, player, enemy, playLanes, "BOLAS");
        await PlayReturningCardAsync(live, player, enemy, playLanes, "THRUMMING_HATCHET");
        CardModel[] returns = player.PlayerCombatState!.AllCards.Where(card => card is Bolas or ThrummingHatchet).ToArray();
        AssertReturningCardsPlayedThisTurn(live, returns);
        string[] order = hatchetFirst ? ["THRUMMING_HATCHET", "BOLAS"] : ["BOLAS", "THRUMMING_HATCHET"];
        foreach (string id in order)
        {
            CardModel actual = returns.Single(card => card.Id.Entry == id);
            foreach (ReturnToHandComparisonLane lane in playLanes)
            {
                _ = lane.BeginStep();lane.Simulator.AddToPile(lane.Simulator.State.FindCard(actual)!, PileType.Exhaust);
            }
            var moved = await CardPileCmd.Add(actual, PileType.Exhaust);
            if (!moved.success) throw new InvalidOperationException("Native fixture exhaust move rejected.");
        }
        AssertReturnToHandLanes(live, player, enemy, playLanes, "exhaust_order");
        for (int index = 0; index < 9; index++)
            await InjectCardAsync(live, player, new() { CardId = "DEFEND_SILENT", Pile = "Hand" });
        await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
        CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
        var parent = root.ForkSimulator();
        string State(CombatPredictionSimulator sim) => ContinuationStamp.CapturePredicted(player, sim,
            ((SimulatedCombatState)sim.State.CombatState).GetPlayerTurnNumber(player), root.Forecast, root.StartTurnNumber).StateText;
        string Full(CombatPredictionSimulator sim) => State(sim) + "\nHISTORY=" + CardContinuationContractHistoryText(sim);
        string parentBefore = Full(parent), liveBefore = ContinuationStamp.CaptureLive(live).StateText;
        var direct = parent.Fork();var opposite = parent.Fork();
        SimPlayerCombatState oppositePlayer = opposite.State.GetPlayerCombatState(player);
        var reversed = oppositePlayer.ExhaustPile.Cards.Reverse().ToArray();
        oppositePlayer.ExhaustPile.Clear();foreach (var card in reversed) oppositePlayer.ExhaustPile.Add(card);
        void Resolve(CombatPredictionSimulator sim)
        {
            using IDisposable isolation = SimulationNotificationIsolation.Enter();
            var combat = (SimulatedCombatState)sim.State.CombatState;
            combat.CurrentSide = CombatSide.Player;combat.RoundNumber++;combat.AdvancePlayerTurn(player);
            combat.BeginSideTurn(player.Creature);
            if (combat.PrepareBeforeHandDraw(sim, player, new TurnStartChoiceCursor(null))
                || !combat.TriggerSideTurnStart(sim, CombatSide.Player, [player.Creature], decrementPlating: true))
                throw new InvalidOperationException("Return capacity fixture introduced an unexpected choice.");
            combat.AssertForkable();
        }
        Resolve(direct);Resolve(opposite);
        string[] ReturningHand(CombatPredictionSimulator sim) => sim.State.GetPlayerCombatState(player).Hand.Cards
            .Where(card => card.Preview is Bolas or ThrummingHatchet).Select(card => card.Preview.Id.Entry).ToArray();
        if (!ReturningHand(direct).SequenceEqual(order.Take(1))
            || !ReturningHand(opposite).SequenceEqual(order.Skip(1)) || Full(direct) == Full(opposite))
            throw new InvalidOperationException("Capacity-sensitive exhaust order difference did not reproduce.");
        if (Full(parent) != parentBefore || ContinuationStamp.CaptureLive(live).StateText != liveBefore)
            throw new InvalidOperationException("Shadow return resolution leaked into parent/live.");
        string beforeNative = Full(direct);
        var children = Enumerable.Range(0, 16).Select(_ => parent.Fork()).ToArray();
        await Task.WhenAll(children.Select(child => Task.Run(() => Resolve(child))));
        foreach (var child in children)
            if (Full(child) != beforeNative || Full(child.Fork()) != beforeNative)
                throw new InvalidOperationException("Parallel return resolution or second-generation Fork differed.");
        if (Full(parent) != parentBefore || ContinuationStamp.CaptureLive(live).StateText != liveBefore)
            throw new InvalidOperationException("Parallel returns leaked into parent/live.");

        live.CurrentSide = CombatSide.Player;live.RoundNumber++;
        player.PlayerCombatState!.IncrementTurnNumber();player.PlayerCombatState.Phase = PlayerTurnPhase.Start;
        try
        {
            await Hook.BeforeHandDraw(live, player, new BlockingPlayerChoiceContext());
            await TriggerActualSideTurnStartAsync(live, CombatSide.Player, player.Creature);
            await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
            if (State(direct) != ContinuationStamp.CaptureLive(live).StateText)
                throw new InvalidOperationException("Native capacity boundary differed in complete state/RNG.");
            AssertSnapshotEqual(CaptureSimulated(direct, (SimulatedCombatState)direct.State.CombatState, player, enemy),
                CaptureActual(live, player, enemy), "RETURN-CAPACITY", "native");
            string[] actualHand = player.PlayerCombatState.Hand.Cards.Where(card => card is Bolas or ThrummingHatchet)
                .Select(card => card.Id.Entry).ToArray();
            string[] actualDiscard = player.PlayerCombatState.DiscardPile.Cards.Where(card => card is Bolas or ThrummingHatchet)
                .Select(card => card.Id.Entry).ToArray();
            if (!actualHand.SequenceEqual(order.Take(1)) || !actualDiscard.SequenceEqual(order.Skip(1)))
                throw new InvalidOperationException("Native overflow did not follow exhaust listener order.");
            _completedChecks.Add("ReturnCapacity:TwoRealPlays:HistoryEligibility:ExhaustOrder:OneHandSlot:NativeFullStateRng:OppositeShadowOutcome:SixteenParallelReturnsTwoGenerationFork:ParentLiveIsolation");
            _completedChecks.Add("TASK_RETURN_CAPACITY " + JsonSerializer.Serialize(new { hatchetFirst, order,
                actualHand, actualDiscard, oppositeHand = ReturningHand(opposite), forkCount = children.Length,
                nativeSha256 = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(State(direct)))),
                parentUnchanged = Full(parent) == parentBefore, actualPrunes = 0, wholeRootCertified = false }));
        }
        finally { player.PlayerCombatState.Phase = PlayerTurnPhase.Play; }
    }
}

